import csv
from datetime import datetime
def read_catalog(cat_fname):
    with open(cat_fname) as cat_fh:
        cat_reader = csv.DictReader(cat_fh)
        ids_by_zone = {}
        for row in cat_reader:
            zone_uri = row['point_uri']
            ts_id = row['timeseries_id']
            ids_by_zone[zone_uri] = ts_id
        return ids_by_zone

ids_by_zone = read_catalog(CATALOG_CSV)

def read_values(ts_id):
    with open(VALUES_CSV) as val_fh:
        val_reader = csv.DictReader(val_fh)
        for row in val_reader:
            if row['timeseries_id'] == ts_id:
                # Parse the timestamp
                ts = datetime.fromisoformat(row['timestamp'])
                if ts == datetime(2018, 10, 10, 13):
                    return float(row['value'])
    return None

temps = []
for zone, ts_id in ids_by_zone.items():
    temp = read_values(ts_id)
    if temp is not None:
        temps += [(zone, temp)]

if temps:
    max_zone_uri, _ = max(temps, key=lambda kv: kv[1])
    max_zone_name = max_zone_uri.split('/')[-1]
else:
    print('No temperature data')
